import java.util.LinkedHashMap;
import java.util.Map;

public class GatewayDemo {
    static Map<String, String> routes = new LinkedHashMap<>();
    static {
        routes.put("/api/orders", "order-service");
        routes.put("/api/users", "user-service");
        routes.put("/api/products", "product-service");
    }
    static String route(String path) {
        // TODO: return service whose key is a prefix of path, else "unknown"
        for (Map.Entry<String, String> e : routes.entrySet()) {
            if (path.startsWith(e.getKey())) return e.getValue();
        }
        return "unknown";
    }
    public static void main(String[] args) {
        System.out.println(route("/api/orders/5"));
        System.out.println(route("/api/users"));
        System.out.println(route("/api/unknown"));
    }
}

import java.util.ArrayList;
import java.util.List;

public class SagaDemo {
    public static void main(String[] args) {
        String[] steps = {"CreateOrder", "ProcessPayment", "FAIL:ReserveInventory"};
        List<String> completed = new ArrayList<>();
        for (String step : steps) {
            if (step.startsWith("FAIL")) {
                System.out.println("Failed at: " + step);
                for (int i = completed.size() - 1; i >= 0; i--) {
                    System.out.println("Compensating: " + completed.get(i));
                }
                break;
            } else {
                System.out.println("Completed: " + step);
                completed.add(step);
            }
        }
    }
}
